#!/usr/bin/env bash
set -Eeuo pipefail
umask 077

GREEN=$'\033[1;32m'; YELLOW=$'\033[1;33m'; RED=$'\033[1;31m'; BLUE=$'\033[1;34m'; RESET=$'\033[0m'
ok(){ printf '%b[OK]%b %s\n' "$GREEN" "$RESET" "$*"; }
info(){ printf '%b[INFO]%b %s\n' "$BLUE" "$RESET" "$*"; }
warn(){ printf '%b[ATENCAO]%b %s\n' "$YELLOW" "$RESET" "$*"; }
fail(){ printf '%b[ERRO]%b %s\n' "$RED" "$RESET" "$*" >&2; exit 1; }

[ "$(id -u)" -eq 0 ] || fail "Execute como root."

STATE="/var/lib/xlx-aprs-dprs"
ETC="/etc/xlx-aprs-dprs"
OPT="/opt/xlx-aprs-dprs"
UNIT="/etc/systemd/system/xlx-aprs-dprs.service"
MARKER="$ETC/install.env"

DASHBOARD=""
if [ -r "$MARKER" ]; then
    # install.env contains only a shell-escaped dashboard path generated by install.sh.
    # shellcheck disable=SC1090
    source "$MARKER"
    DASHBOARD="${DASHBOARD_DIR:-}"
fi

STAMP="$(date +%Y%m%d_%H%M%S)"
DEST="${1:-/root/backups-xlx-aprs-dprs/BACKUP_${STAMP}}"
STAGE="$DEST/stage"
ARCHIVE="$DEST/xlx-aprs-dprs-backup.tar.gz"

mkdir -p "$STAGE/config" "$STAGE/state" "$STAGE/systemd" "$STAGE/opt" "$STAGE/web"
chmod 700 "$DEST" "$STAGE"

info "Criando backup consistente do APRS/D-PRS..."

[ ! -d "$ETC" ] || cp -a "$ETC/." "$STAGE/config/"
[ ! -d "$OPT" ] || cp -a "$OPT/." "$STAGE/opt/"
[ ! -f "$UNIT" ] || cp -a "$UNIT" "$STAGE/systemd/"

if [ -n "$DASHBOARD" ] && [ -d "$DASHBOARD/aprs-dprs" ]; then
    cp -a "$DASHBOARD/aprs-dprs/." "$STAGE/web/"
fi

# SQLite online backup API: produces consistent DB copies without stopping the gateway.
python3 - "$STATE" "$STAGE/state" <<'PY'
from pathlib import Path
import shutil, sqlite3, sys

src = Path(sys.argv[1])
dst = Path(sys.argv[2])
dst.mkdir(parents=True, exist_ok=True)

for name in ("digital-lab.sqlite", "accounts.sqlite"):
    p = src / name
    if not p.is_file():
        continue
    out = dst / name
    s = sqlite3.connect(f"file:{p}?mode=ro", uri=True, timeout=10)
    d = sqlite3.connect(out)
    try:
        s.backup(d)
    finally:
        d.close()
        s.close()

for name in ("public.json", "operator-rate.json"):
    p = src / name
    if p.is_file():
        shutil.copy2(p, dst / name)
PY

tar -C "$STAGE" -czf "$ARCHIVE" .
sha256sum "$ARCHIVE" > "$DEST/SHA256SUMS.txt"
chmod 600 "$ARCHIVE" "$DEST/SHA256SUMS.txt"

ok "Backup criado."
echo "Arquivo : $ARCHIVE"
echo "SHA-256 : $(awk '{print $1}' "$DEST/SHA256SUMS.txt")"
echo "STATUS=BACKUP_OK"
